"use client"

import { useEffect, useState } from "react"
import type { RealtimePrediction } from "tfl-ts"
import { RailArrivalsBoard } from "@/components/tfl/arrivals/rail-arrivals-board"
import { getStopArrivalsAction } from "@/lib/tfl/live-arrivals-action"
import { useArrivalsBoardUiState } from "@/lib/tfl/use-arrivals-board-ui-state"

const DEFAULT_STOP_ID = "940GZZLUOXC"
const POLL_MS = 20_000

/**
 * Docs/demo helper: polls a stop and passes predictions into {@link RailArrivalsBoard}.
 * Prefer using `RailArrivalsBoard` with `data` directly in applications.
 *
 * @deprecated Prefer RailArrivalsBoard + your own fetch. Legacy registry name only.
 */
export const LiveArrivalsBoard = ({
  stopPointId = DEFAULT_STOP_ID,
  stopName,
}: {
  stopPointId?: string
  stopName?: string
}) => {
  const [data, setData] = useState<RealtimePrediction[]>([])
  const [fetchedAt, setFetchedAt] = useState<number | null>(null)
  const [fetchError, setFetchError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const boardState = useArrivalsBoardUiState(data.length, fetchError, "rail")

  useEffect(() => {
    let cancelled = false
    let timer: ReturnType<typeof setTimeout> | undefined

    const load = async () => {
      try {
        const result = await getStopArrivalsAction(stopPointId)
        if (cancelled) return
        if (!result.ok) {
          setFetchError(result.error)
          setData([])
        } else {
          setFetchError(null)
          setData(result.arrivals)
          setFetchedAt(Date.now())
        }
      } catch {
        if (!cancelled) setFetchError("Failed to load arrivals.")
      } finally {
        if (!cancelled) {
          setLoading(false)
          timer = setTimeout(load, POLL_MS)
        }
      }
    }

    void load()
    return () => {
      cancelled = true
      if (timer) clearTimeout(timer)
    }
  }, [stopPointId])

  return (
    <RailArrivalsBoard
      data={data}
      now={fetchedAt ?? undefined}
      stopName={stopName}
      loading={loading}
      error={boardState.error}
      emptyKind={boardState.emptyKind}
    />
  )
}

export { RailArrivalsBoard } from "@/components/tfl/arrivals/rail-arrivals-board"
export { ArrivalsBoardSkeleton } from "@/components/tfl/arrivals/arrivals-board-view"

"use server"

import type { RealtimePrediction } from "tfl-ts"
import {
  getCachedLineArrivals,
  getCachedStopArrivals,
  isDemoLineArrivalsSet,
  isDemoStopArrivalsId,
} from "@/lib/tfl/cached-stop-arrivals"

export type GetStopArrivalsResult =
  { ok: true; arrivals: RealtimePrediction[] } | { ok: false; error: string }

/** @deprecated Use RealtimePrediction from tfl-ts. */
export type LiveArrival = RealtimePrediction

/**
 * Docs-demo arrivals fetch for the site key path.
 * Only allowlisted demo stop IDs are served (shared cache).
 * Arbitrary stop IDs are rejected so this cannot be used as an open TfL proxy.
 */
export async function getStopArrivalsAction(
  stopPointId: string
): Promise<GetStopArrivalsResult> {
  const trimmed = stopPointId.trim()
  if (!trimmed) return { ok: false, error: "No stop selected." }

  if (!isDemoStopArrivalsId(trimmed)) {
    return {
      ok: false,
      error:
        "This stop is not available on the site key. Add your own TfL API key.",
    }
  }

  try {
    const arrivals = await getCachedStopArrivals(trimmed)
    return { ok: true, arrivals }
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Failed to fetch arrivals."
    return { ok: false, error: message }
  }
}

export type GetLineArrivalsResult =
  { ok: true; arrivals: RealtimePrediction[] } | { ok: false; error: string }

/**
 * Network-wide line arrivals for shared-track identity.
 * Only curated line sets are served so this cannot be used as an open TfL proxy.
 */
export async function getLineArrivalsAction(
  lineIds: readonly string[]
): Promise<GetLineArrivalsResult> {
  const trimmed = [...new Set(lineIds.map((id) => id.trim()).filter(Boolean))]
  if (trimmed.length < 2) {
    return { ok: false, error: "Need at least two line ids." }
  }
  if (!isDemoLineArrivalsSet(trimmed)) {
    return {
      ok: false,
      error: "This line set is not available on the site key.",
    }
  }

  try {
    const arrivals = await getCachedLineArrivals(trimmed)
    return { ok: true, arrivals }
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Failed to fetch line arrivals."
    return { ok: false, error: message }
  }
}

"use client"

import { useEffect, useState, useSyncExternalStore } from "react"
import {
  resolveArrivalsEmptyKind,
  type ArrivalsEmptyKind,
} from "@/lib/tfl/arrivals-empty"

const LOAD_ERROR = "Couldn't load arrivals."

type ArrivalsBoardUiState = {
  error: string | null
  emptyKind: ArrivalsEmptyKind
}

const NOON_SENTINEL_MS = Date.UTC(2020, 0, 1, 12, 0, 0)

// `useSyncExternalStore`'s snapshot must be a *stable* cached value — it is
// re-read on every render, and `Date.now()` returns a new value on every
// call. Reading it directly here would make React see the store as "changed"
// on every render, forcing another render, forever (Maximum update depth
// exceeded). Instead, only mutate the cache inside the subscribe callback,
// which React guarantees runs client-side only, never during SSR/prerender.
let cachedNowMs = NOON_SENTINEL_MS

const subscribeToMinuteClock = (onStoreChange: () => void) => {
  const sync = () => {
    cachedNowMs = Date.now()
    onStoreChange()
  }
  sync()
  const id = window.setInterval(sync, 60_000)
  return () => window.clearInterval(id)
}

const getClockSnapshot = () => cachedNowMs
const getServerClockSnapshot = () => NOON_SENTINEL_MS

/**
 * Client-side empty/error presentation for live demos and polling boards.
 * Distinguishes offline vs fetch failure vs night-ended vs plain empty.
 */
export const useArrivalsBoardUiState = (
  rowCount: number,
  fetchError: string | null,
  domain: "rail" | "bus" | "river" = "rail",
  lineIds?: readonly string[]
): ArrivalsBoardUiState => {
  const [offline, setOffline] = useState(false)
  const nowMs = useSyncExternalStore(
    subscribeToMinuteClock,
    getClockSnapshot,
    getServerClockSnapshot
  )

  useEffect(() => {
    const sync = () => setOffline(!navigator.onLine)
    queueMicrotask(sync)
    window.addEventListener("online", sync)
    window.addEventListener("offline", sync)
    return () => {
      window.removeEventListener("online", sync)
      window.removeEventListener("offline", sync)
    }
  }, [])

  if (fetchError && !offline) {
    return { error: LOAD_ERROR, emptyKind: "empty" }
  }

  return {
    error: null,
    emptyKind:
      resolveArrivalsEmptyKind({
        rowCount,
        offline: offline && rowCount === 0,
        domain,
        nowMs,
        lineIds,
      })?.kind ?? "empty",
  }
}

/**
 * Why an arrivals board has no rows. Callers resolve this from fetch result +
 * clock + optional line-status *signal*; the board only paints arrivals copy.
 *
 * This module answers “are there trains coming?”, not line status. Status
 * kinds/validity may classify an empty list. Never pass reason text, Service
 * Closed labels, or engineering copy through to the UI.
 */
import {
  getStatusKind,
  getWorstCurrentStatus,
  normalizeLineId,
  STATION_HUBS,
  type LineStatusLike,
  type StatusKind,
} from "tfl-ts"
import {
  LONDON_TIME_ZONE,
  londonDateKey,
  londonWeekdayLong,
} from "@/lib/tfl/london-dates"
import { isCurrentAnnouncement } from "@/lib/tfl/status-reason"
import type { StatusLine } from "@/lib/tfl/status-types"

/** Night Tube lines. Night Overground is not in this set. */
export const NIGHT_TUBE_LINE_IDS = [
  "central",
  "jubilee",
  "northern",
  "piccadilly",
  "victoria",
] as const

const NIGHT_TUBE_LINE_ID_SET = new Set<string>(NIGHT_TUBE_LINE_IDS)

export type ArrivalsEmptyKind = "empty" | "ended" | "offline" | "disrupted"

export type ArrivalsEmptyState = {
  kind: ArrivalsEmptyKind
  /**
   * Later-today run end, when PlannedWork actually resumes during this
   * operating day. Overnight traffic-day ends and later calendar days omit it.
   */
  resumeMs?: number
}

export const ARRIVALS_EMPTY_COPY: Record<ArrivalsEmptyKind, string> = {
  empty: "No arrivals right now.",
  ended: "Service has ended for tonight.",
  offline: "You're offline. Arrivals will update when you're back.",
  disrupted: "No service.",
}

/**
 * River predictions can be `[]` while line status is still Good Service
 * (RB4 / Woolwich Ferry). Do not claim that no boats are due.
 */
export const RIVER_ARRIVALS_EMPTY_COPY = "No live departure times available."

/** Per-route fallback when a bus/river group is empty. Rail uses {@link arrivalsLineEmptyCopy}. */
export const ARRIVALS_LINE_EMPTY_COPY = "No information"

/** Last spare tile on a short page that still has arrivals. */
export const ARRIVALS_END_COPY = "No more arrivals"

/** Narrow-width step of `ARRIVALS_END_COPY`. Accessible name stays the full phrase. */
export const ARRIVALS_END_COPY_SHORT = "No more"

/**
 * Subgroup heading when TfL sends `Platform Unknown` (or no platform at all)
 * on a live prediction. Distinct from a bound with no heading — that is
 * reserved for true “no bound metadata” (bus lists, empty unseeded lines).
 */
export const ARRIVALS_PLATFORM_UNKNOWN_HEADING = "Platform to be confirmed"

const DELAY_ONLY_DESCRIPTIONS = new Set([
  "minor delays",
  "severe delays",
  "reduced service",
  "diverted",
  "issues reported",
])

/** Official labels that do not explain missing or present trains. */
const ARRIVALS_CHIP_HIDE = new Set([
  "good service",
  "special service",
  "no issues",
  "no exceptional delays",
  "no step free access",
  "information",
  "exit only",
  "change of frequency",
])

/** Closure / suspension labels that explain an empty board. */
const ARRIVALS_CHIP_ON_EMPTY = new Set([
  "planned closure",
  "part closure",
  "part closed",
  "service closed",
  "not running",
  "suspended",
  "part suspended",
  "closed",
  "no service",
  "bus service",
  "closure",
])

/** Labels that explain a group that still has trains. */
const ARRIVALS_CHIP_ON_TRAINS = new Set([
  "minor delays",
  "severe delays",
  "reduced service",
  "diverted",
  "issues reported",
  "planned closure",
  "part closure",
  "part closed",
  "suspended",
  "part suspended",
])

/** May create a following leftover page when the last page is exactly full. */
const ARRIVALS_LEFTOVER_CAN_ADD_PAGE = new Set([
  "severe delays",
  "suspended",
  "part suspended",
])

/** Arrivals-owned leftover-tile sentence. Never stitched to the chip. */
export const ARRIVALS_LEFTOVER_SENTENCE = "Expect longer waits."

export type ArrivalsLeftoverStatus = {
  label: string
  sentence: string
  canAddPage: boolean
}

const londonHourFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  hour: "2-digit",
  hourCycle: "h23",
})

const londonClockPartsFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23",
})

/** Europe/London hour (0–23) for an instant. Pass `nowMs` — never default the clock here. */
export const londonHour = (nowMs: number): number => {
  const hour = londonHourFormatter
    .formatToParts(new Date(nowMs))
    .find((part) => part.type === "hour")?.value
  return hour ? Number(hour) : 0
}

/** Europe/London clock for a known instant, e.g. `10:30`. */
export const formatLondonClockTime = (ms: number): string => {
  const parts = londonClockPartsFormatter.formatToParts(new Date(ms))
  const hour = parts.find((part) => part.type === "hour")?.value ?? "00"
  const minute = parts.find((part) => part.type === "minute")?.value ?? "00"
  return `${hour}:${minute}`
}

/**
 * Rough Underground closed window in London local time. Night buses still run,
 * so prefer `empty` for bus boards unless the caller forces `ended`.
 */
export const isLikelyRailServiceEnded = (nowMs: number): boolean => {
  const hour = londonHour(nowMs)
  return hour >= 1 && hour < 5
}

export const isNightTubeLine = (lineId: string): boolean =>
  NIGHT_TUBE_LINE_ID_SET.has(normalizeLineId(lineId))

/**
 * Friday-into-Saturday and Saturday-into-Sunday mornings, when Night Tube
 * runs. Bank-holiday extras are not modelled.
 */
export const isLondonNightTubeMorning = (nowMs: number): boolean => {
  if (!isLikelyRailServiceEnded(nowMs)) return false
  const weekday = londonWeekdayLong(nowMs)
  return weekday === "Saturday" || weekday === "Sunday"
}

/**
 * Overnight `ended` only for non-Night-Tube rail. Night Tube lines skip
 * Fri→Sat and Sat→Sun mornings. Ordinary Mon–Thu 01:00–05:00 is fine.
 */
export const lineLikelyFinishedOvernight = (
  lineId: string,
  nowMs: number
): boolean => {
  if (!isLikelyRailServiceEnded(nowMs)) return false
  if (isNightTubeLine(lineId) && isLondonNightTubeMorning(nowMs)) return false
  return true
}

export const arrivalsDisruptedCopy = (resumeMs?: number): string =>
  resumeMs === undefined
    ? ARRIVALS_EMPTY_COPY.disrupted
    : `No service until ${formatLondonClockTime(resumeMs)}.`

/** Successful empty: none, overnight ended, or a short disruption note. */
export const arrivalsLineEmptyCopy = (
  state: ArrivalsEmptyState | ArrivalsEmptyKind | null
): string => {
  if (state == null) return ARRIVALS_EMPTY_COPY.empty
  if (typeof state === "string") {
    return state === "disrupted"
      ? ARRIVALS_EMPTY_COPY.disrupted
      : ARRIVALS_EMPTY_COPY[state]
  }
  if (state.kind === "disrupted") return arrivalsDisruptedCopy(state.resumeMs)
  return ARRIVALS_EMPTY_COPY[state.kind]
}

/** Line status as a classification signal — id + current statuses only. */
export type ArrivalsStatusSignal = Pick<StatusLine, "id" | "lineStatuses">

type ValidityPeriodLike = {
  from?: string
  to?: string
  fromDate?: string
  toDate?: string
  isNow?: boolean
}

const periodField = (
  period: ValidityPeriodLike,
  edge: "from" | "to"
): string | undefined =>
  edge === "from"
    ? (period.from ?? period.fromDate)
    : (period.to ?? period.toDate)

const periodOverlapsNow = (
  period: ValidityPeriodLike,
  nowMs: number
): boolean => {
  const from = periodField(period, "from")
  const to = periodField(period, "to")
  if (!from && !to) return true
  const fromMs = from ? Date.parse(from) : Number.NEGATIVE_INFINITY
  const toMs = to ? Date.parse(to) : Number.POSITIVE_INFINITY
  if (Number.isNaN(fromMs) || Number.isNaN(toMs)) return true
  return nowMs >= fromMs && nowMs <= toMs
}

type ParsedValidityPeriod = {
  fromMs: number
  toMs: number | undefined
}

const parseValidityPeriod = (
  period: ValidityPeriodLike
): ParsedValidityPeriod | undefined => {
  const from = periodField(period, "from")
  const to = periodField(period, "to")
  const fromMs = from ? Date.parse(from) : Number.NEGATIVE_INFINITY
  const toMs = to ? Date.parse(to) : undefined
  if (Number.isNaN(fromMs)) return undefined
  if (toMs !== undefined && Number.isNaN(toMs)) return undefined
  return { fromMs, toMs }
}

/** TfL splits "Sat from 1400, all day Sunday" across the overnight gap. */
const OVERNIGHT_CONTINUATION_MS = 8 * 3_600_000

const isOvernightContinuation = (
  endMs: number,
  nextFromMs: number
): boolean => {
  if (nextFromMs <= endMs) return true
  if (nextFromMs - endMs > OVERNIGHT_CONTINUATION_MS) return false
  return londonHour(endMs) < 5
}

const continuesRun = (
  endMs: number,
  period: ParsedValidityPeriod
): boolean =>
  period.fromMs <= endMs || isOvernightContinuation(endMs, period.fromMs)

/**
 * End of the current PlannedWork run: overlapping `toDate`/`to`, then later
 * overnight-split slices on the same row. Ignores `isNow` and never reads
 * `reason`. Open-ended current or continued slices return `undefined`.
 */
export const overlappingValidityToDateMs = (
  status: LineStatusLike | undefined,
  nowMs: number
): number | undefined => {
  const raw = status?.validityPeriods ?? []
  const overlapping = raw.filter((period) => periodOverlapsNow(period, nowMs))
  if (overlapping.length === 0) return undefined

  const overlappingEnds: number[] = []
  for (const period of overlapping) {
    const to = periodField(period, "to")
    if (!to) return undefined
    const toMs = Date.parse(to)
    if (Number.isNaN(toMs)) continue
    overlappingEnds.push(toMs)
  }
  if (overlappingEnds.length === 0) return undefined

  let endMs = Math.max(...overlappingEnds)
  const parsed = raw
    .map(parseValidityPeriod)
    .filter((period): period is ParsedValidityPeriod => period !== undefined)

  let grew = true
  while (grew) {
    grew = false
    for (const period of parsed) {
      if (!continuesRun(endMs, period)) continue
      if (period.toMs === undefined) return undefined
      if (period.toMs > endMs) {
        endMs = period.toMs
        grew = true
      }
    }
  }
  return endMs
}

/** Clock copy is only honest for a same-calendar-day, in-service resume. */
const isLaterTodayResumeClock = (resumeMs: number, nowMs: number): boolean => {
  if (isLikelyRailServiceEnded(resumeMs)) return false
  return londonDateKey(new Date(resumeMs)) === londonDateKey(new Date(nowMs))
}

const statusDescription = (status: LineStatusLike): string =>
  (status.statusSeverityDescription ?? status.severityDescription ?? "")
    .trim()
    .toLowerCase()

/** Official TfL `statusSeverityDescription` as sent — never reason text. */
export const officialStatusDescription = (
  status: LineStatusLike | undefined
): string | undefined => {
  const label = (
    status?.statusSeverityDescription ??
    status?.severityDescription ??
    ""
  ).trim()
  return label || undefined
}

const isDelayOnlyStatus = (status: LineStatusLike): boolean =>
  DELAY_ONLY_DESCRIPTIONS.has(statusDescription(status))

const isServiceClosedStatus = (status: LineStatusLike | undefined): boolean =>
  Boolean(status && statusDescription(status) === "service closed")

type AffectedStopLike = {
  id?: string
  naptanId?: string
  stationNaptan?: string
  stationNaptanId?: string
}

type AffectedRouteLike = {
  isEntireRouteSection?: boolean
  routeSectionNaptanEntrySequence?: Array<{ stopPoint?: AffectedStopLike }>
  stops?: AffectedStopLike[]
}

type ArrivalsDisruptionLike = {
  category?: string
  affectedStops?: AffectedStopLike[]
  affectedRoutes?: AffectedRouteLike[]
}

type ArrivalsLineStatus = LineStatusLike & {
  disruption?: ArrivalsDisruptionLike
}

const stopIdentityIds = (stop: AffectedStopLike | undefined): string[] => {
  if (!stop) return []
  return [
    ...new Set(
      [stop.stationNaptan, stop.stationNaptanId, stop.naptanId, stop.id]
        .map((id) => id?.trim())
        .filter((id): id is string => Boolean(id))
    ),
  ]
}

const disruptionOf = (status: LineStatusLike): ArrivalsDisruptionLike =>
  (status as ArrivalsLineStatus).disruption ?? {}

/**
 * Hub + member Naptans for a board stop. Empty when the board has no stop id
 * — callers then keep line-wide status (docs fixtures, unscoped demos).
 */
export const stationIdentityIdsForStop = (
  stopPointId: string | undefined
): string[] => {
  const id = stopPointId?.trim()
  if (!id) return []
  const ids = new Set<string>([id])
  const hub = STATION_HUBS[id]
  if (hub?.hubId) ids.add(hub.hubId)
  for (const member of hub?.members ?? []) ids.add(member.id)
  return [...ids]
}

const extractAffectedStopIds = (status: LineStatusLike): string[] => {
  const disruption = disruptionOf(status)
  const ids: string[] = []
  for (const route of disruption.affectedRoutes ?? []) {
    for (const entry of route.routeSectionNaptanEntrySequence ?? []) {
      ids.push(...stopIdentityIds(entry.stopPoint))
    }
    for (const stop of route.stops ?? []) ids.push(...stopIdentityIds(stop))
  }
  for (const stop of disruption.affectedStops ?? []) {
    ids.push(...stopIdentityIds(stop))
  }
  return [...new Set(ids)]
}

/**
 * Whether a `getStatus({ detail: true })` row applies at this station.
 * Entire-route rows and payloads with no geography stay relevant. Structured
 * affected stops / route naptans win over line-wide leftover copy — never
 * parse `reason`.
 */
export const statusAffectsStation = (
  status: LineStatusLike,
  stationIds: readonly string[] | undefined
): boolean => {
  if (!stationIds?.length) return true
  const disruption = disruptionOf(status)
  if (disruption.affectedRoutes?.some((route) => route.isEntireRouteSection)) {
    return true
  }
  const affectedIds = extractAffectedStopIds(status)
  if (affectedIds.length === 0) return true
  const wanted = new Set(stationIds)
  return affectedIds.some((id) => wanted.has(id))
}

const statusesAffectingStation = (
  statuses: readonly LineStatusLike[] | undefined,
  stationIds: readonly string[] | undefined
): LineStatusLike[] =>
  (statuses ?? []).filter((status) => statusAffectsStation(status, stationIds))

/**
 * Current closure / suspension / planned work — not Good Service, info, or
 * delay-only rows. Uses `isCurrentAnnouncement` (clock overlap, not `isNow`).
 */
export const isCurrentArrivalsDisruption = (
  status: LineStatusLike | undefined,
  nowMs: number
): boolean => {
  if (!status || !isCurrentAnnouncement(status, nowMs)) return false
  const kind = getStatusKind(status)
  if (kind === "good" || kind === "info") return false
  if (isDelayOnlyStatus(status)) return false
  return kind === "plannedWork" || kind === "closed" || kind === "incident"
}

/**
 * Current tfl-ts status kind per line, using validity windows at `nowMs`.
 * Reasons / descriptions are ignored for copy.
 */
export const indexArrivalsStatusKinds = (
  lines: readonly ArrivalsStatusSignal[] | undefined,
  nowMs?: number
): Readonly<Record<string, StatusKind>> => {
  const out: Record<string, StatusKind> = {}
  if (!lines?.length) return out
  const statusNow = nowMs !== undefined ? { now: nowMs } : undefined
  for (const line of lines) {
    const id = normalizeLineId(line.id ?? "")
    if (!id) continue
    const worst = getWorstCurrentStatus(line.lineStatuses, statusNow)
    out[id] = worst ? getStatusKind(worst) : "good"
  }
  return out
}

const groupFinishedOvernight = (
  lineIds: readonly string[],
  nowMs: number
): boolean => {
  const ids = lineIds.map((id) => id.trim()).filter(Boolean)
  if (ids.length === 0) return true
  return ids.every((id) => lineLikelyFinishedOvernight(id, nowMs))
}

const servingLineIds = (lineIds: readonly string[] | undefined): string[] =>
  (lineIds ?? []).map((id) => id.trim()).filter(Boolean)

const indexStatusSignals = (
  lines: readonly ArrivalsStatusSignal[] | undefined
): Readonly<Record<string, ArrivalsStatusSignal>> => {
  const out: Record<string, ArrivalsStatusSignal> = {}
  for (const line of lines ?? []) {
    const id = normalizeLineId(line.id ?? "")
    if (id) out[id] = line
  }
  return out
}

/**
 * Status kinds never upgrade a successful arrivals `[]` to unavailable.
 */
export const statusKindForcesArrivalsUnavailable = (
  _kind: StatusKind | undefined
): false => false

/**
 * Worst current row across a group (shared-platform merge included).
 * Uses `getWorstCurrentStatus` — Circle Planned Closure (4) beats District
 * Part Closure (5).
 */
export const groupWorstCurrentStatus = (
  lineIds: readonly string[],
  lineStatus: readonly ArrivalsStatusSignal[] | undefined,
  nowMs?: number,
  stationIds?: readonly string[]
): LineStatusLike | undefined => {
  const ids = servingLineIds(lineIds)
  if (!ids.length || !lineStatus?.length) return undefined
  const byId = indexStatusSignals(lineStatus)
  const statuses: LineStatusLike[] = []
  for (const id of ids) {
    const line = byId[normalizeLineId(id)]
    statuses.push(...statusesAffectingStation(line?.lineStatuses, stationIds))
  }
  if (!statuses.length) return undefined
  return getWorstCurrentStatus(
    statuses,
    nowMs !== undefined ? { now: nowMs } : undefined
  )
}

type ResolveArrivalsStatusChipOptions = {
  lineIds: readonly string[]
  hasTrains: boolean
  emptyKind?: ArrivalsEmptyKind | null
  lineStatus?: readonly ArrivalsStatusSignal[]
  nowMs?: number
  hasError?: boolean
  /** Board stop. Filters line status to geography that affects this station. */
  stopPointId?: string
}

/**
 * QuietChip label for arrivals. Official description only; never stitched
 * into the arrivals sentence and never taken from `reason`.
 */
export const resolveArrivalsStatusChip = ({
  lineIds,
  hasTrains,
  emptyKind,
  lineStatus,
  nowMs,
  hasError = false,
  stopPointId,
}: ResolveArrivalsStatusChipOptions): string | null => {
  if (hasError || emptyKind === "offline") return null
  const worst = groupWorstCurrentStatus(
    lineIds,
    lineStatus,
    nowMs,
    stationIdentityIdsForStop(stopPointId)
  )
  const label = officialStatusDescription(worst)
  if (!label) return null
  const key = label.toLowerCase()
  if (ARRIVALS_CHIP_HIDE.has(key)) return null
  if (hasTrains) {
    if (key === "service closed") return null
    return ARRIVALS_CHIP_ON_TRAINS.has(key) ? label : null
  }
  if (DELAY_ONLY_DESCRIPTIONS.has(key)) return null
  return ARRIVALS_CHIP_ON_EMPTY.has(key) ? label : null
}

/**
 * Leftover rail tile when a group still has trains. Empty boards stay on the
 * empty-row path. Delay-only labels never add a page. Pass `stopPointId` so a
 * part closure that does not include this station is not painted here.
 */
export const resolveArrivalsLeftoverStatus = ({
  lineIds,
  lineStatus,
  nowMs,
  hasError = false,
  stopPointId,
}: {
  lineIds: readonly string[]
  lineStatus?: readonly ArrivalsStatusSignal[]
  nowMs?: number
  hasError?: boolean
  stopPointId?: string
}): ArrivalsLeftoverStatus | null => {
  const label = resolveArrivalsStatusChip({
    lineIds,
    hasTrains: true,
    lineStatus,
    nowMs,
    hasError,
    stopPointId,
  })
  if (!label) return null
  return {
    label,
    sentence: ARRIVALS_LEFTOVER_SENTENCE,
    canAddPage: ARRIVALS_LEFTOVER_CAN_ADD_PAGE.has(label.toLowerCase()),
  }
}

const plannedWorkResumeMs = (
  status: LineStatusLike,
  nowMs: number
): number | undefined => {
  if (status.disruption?.category !== "PlannedWork") return undefined
  if (isDelayOnlyStatus(status)) return undefined
  const resumeMs = overlappingValidityToDateMs(status, nowMs)
  if (resumeMs === undefined) return undefined
  return isLaterTodayResumeClock(resumeMs, nowMs) ? resumeMs : undefined
}

const resolveGroupDisruption = (
  lineIds: readonly string[],
  lineStatus: readonly ArrivalsStatusSignal[] | undefined,
  nowMs: number,
  stationIds?: readonly string[]
): ArrivalsEmptyState | null => {
  if (!lineIds.length || !lineStatus?.length) return null
  const byId = indexStatusSignals(lineStatus)
  const resumes: number[] = []
  for (const id of lineIds) {
    const line = byId[normalizeLineId(id)]
    const worst = getWorstCurrentStatus(
      statusesAffectingStation(line?.lineStatuses, stationIds),
      { now: nowMs }
    )
    statusKindForcesArrivalsUnavailable(
      worst ? getStatusKind(worst) : undefined
    )
    if (!isCurrentArrivalsDisruption(worst, nowMs) || !worst) return null
    const lineResumeMs = plannedWorkResumeMs(worst, nowMs)
    if (lineResumeMs !== undefined) resumes.push(lineResumeMs)
  }
  const sameResume =
    resumes.length === lineIds.length &&
    resumes.every((value) => value === resumes[0])
  return sameResume
    ? { kind: "disrupted", resumeMs: resumes[0] }
    : { kind: "disrupted" }
}

/**
 * Successful `[]`: current disruption (with optional resume clock) wins over
 * overnight `ended`. Closed / planned work never become unavailable and never
 * contribute reason text.
 */
const classifySuccessfulRailEmpty = (
  lineIds: readonly string[] | undefined,
  nowMs: number,
  lineStatus: readonly ArrivalsStatusSignal[] | undefined,
  stationIds?: readonly string[]
): ArrivalsEmptyState => {
  const ids = servingLineIds(lineIds)
  const disrupted = resolveGroupDisruption(ids, lineStatus, nowMs, stationIds)
  const overnight =
    ids.length === 0
      ? isLikelyRailServiceEnded(nowMs)
      : groupFinishedOvernight(ids, nowMs)
  if (disrupted) {
    // Timetable / overnight Service Closed keeps ended + chip, not "No service."
    if (
      overnight &&
      disrupted.resumeMs === undefined &&
      isServiceClosedStatus(
        groupWorstCurrentStatus(ids, lineStatus, nowMs, stationIds)
      )
    ) {
      return { kind: "ended" }
    }
    return disrupted
  }
  if (!isLikelyRailServiceEnded(nowMs)) return { kind: "empty" }
  if (ids.length === 0) return { kind: "ended" }
  return { kind: groupFinishedOvernight(ids, nowMs) ? "ended" : "empty" }
}

type ResolveArrivalsEmptyKindOptions = {
  rowCount: number
  /** Fetch/render failure — board uses `error` instead. Status cannot override. */
  hasError?: boolean
  offline?: boolean
  /** Rail uses the overnight `ended` heuristic; bus and river do not. */
  domain?: "rail" | "bus" | "river"
  nowMs: number
  /**
   * Serving / selected line ids for station-level aggregation. Ended only when
   * every listed line would be finished. Disruption only when every listed
   * line is currently disrupted. Omit to keep the unseeded network behaviour
   * (overnight → ended).
   */
  lineIds?: readonly string[]
  /** Optional current line status. Never makes a successful `[]` unavailable. */
  lineStatus?: readonly ArrivalsStatusSignal[]
  /** Board stop. Filters disruption empty-copy to this station's geography. */
  stopPointId?: string
}

/**
 * Pick an empty state when there are no rows. Returns `null` when the board
 * should show arrivals or an error instead.
 */
export const resolveArrivalsEmptyKind = ({
  rowCount,
  hasError = false,
  offline = false,
  domain = "rail",
  nowMs,
  lineIds,
  lineStatus,
  stopPointId,
}: ResolveArrivalsEmptyKindOptions): ArrivalsEmptyState | null => {
  if (hasError || rowCount > 0) return null
  if (offline) return { kind: "offline" }
  if (domain !== "rail") return { kind: "empty" }
  return classifySuccessfulRailEmpty(
    lineIds,
    nowMs,
    lineStatus,
    stationIdentityIdsForStop(stopPointId)
  )
}

type ResolveLineArrivalsEmptyKindOptions = {
  /** Group members (one id, or a shared-track merge). */
  lineIds: readonly string[]
  rowCount: number
  /** Fetch timestamp. Omit to refuse the overnight `ended` claim. */
  nowMs?: number
  /** Optional current line status. Closed / planned work may become `disrupted`. */
  lineStatus?: readonly ArrivalsStatusSignal[]
  /** Board stop. Filters disruption empty-copy to this station's geography. */
  stopPointId?: string
}

/**
 * Per-group empty state after a successful fetch. A group that still has any
 * prediction stays `null` — empty sibling bounds stay local (`none`).
 * `disrupted` only when every member is currently disrupted. `ended` only when
 * every member would be finished overnight and no current disruption applies.
 */
export const resolveLineArrivalsEmptyKind = ({
  lineIds,
  rowCount,
  nowMs,
  lineStatus,
  stopPointId,
}: ResolveLineArrivalsEmptyKindOptions): ArrivalsEmptyState | null => {
  if (rowCount > 0) return null
  if (nowMs === undefined) return { kind: "empty" }
  return classifySuccessfulRailEmpty(
    lineIds,
    nowMs,
    lineStatus,
    stationIdentityIdsForStop(stopPointId)
  )
}

/**
 * Painted bus stop letters — the red circle on a flag / arrivals header.
 *
 * Probed 2026-08-15 (Wapping, The Highway, Trafalgar Square, Oxford Circus,
 * Liverpool Street):
 * - Real letters are 1–2 A–Z (`E`, `RG`, `CV`). Never invent from the name.
 * - NaPTAN suffix is not the letter (`490000251W` is Stop R, not W).
 * - `->W` / `->E` are compass markers on stops with no painted letter.
 * - Search hits are thin (id / name / towards). Letter lives on
 *   `stopPoint.get` / `getByGeoPoint`, or as `platformName` on arrivals.
 */

const PAINTED_STOP_LETTER = /^[A-Z]{1,2}$/

/** TfL sometimes sends the literal string `"null"` instead of omitting a field. */
export const usableTflText = (value?: string | null): string | undefined => {
  const trimmed = value?.trim()
  if (!trimmed || /^(null|undefined)$/i.test(trimmed)) return undefined
  return trimmed
}

/** `Stop RG` / `rg` / `E` → `RG` / `E`. Arrows and stands → undefined. */
export const normaliseBusStopLetter = (
  raw?: string | null
): string | undefined => {
  const stripped = raw
    ?.replace(/^stop\s+/i, "")
    .trim()
    .toUpperCase()
  if (!stripped || !PAINTED_STOP_LETTER.test(stripped)) return undefined
  return stripped
}

export const readStopLetter = (
  stopLetter?: string | null,
  indicator?: string | null
): string | undefined =>
  normaliseBusStopLetter(stopLetter) ?? normaliseBusStopLetter(indicator)

export const getBusStopLetterFromPlatform = (
  platformName?: string | null
): string | null => normaliseBusStopLetter(platformName) ?? null

export const resolveBusStopLetter = (
  stopLetter: string | undefined,
  rows: readonly { platformName?: string }[]
): string | null => {
  const fromProp = normaliseBusStopLetter(stopLetter)
  if (fromProp) return fromProp
  for (const row of rows) {
    const letter = getBusStopLetterFromPlatform(row.platformName)
    if (letter) return letter
  }
  return null
}

/**
 * Chip labels keep normal casing (e.g. “Platform 4”, “Plat 4”).
 * Put this on the painted text node, not the flex chrome — then `items-center`
 * on the chip centres the cap-height box (uppercase X), not the em-square.
 * Chips never show descenders (g/y/p/q), so cap→alphabetic is the optical
 * vertical centre. Do not use x-height (`ex`) trim.
 */
export const CHIP_CAP_TEXT_BOX_CLASS =
  "leading-none [text-box:trim-both_cap_alphabetic]"

/**
 * Shared identity-chip width. Bus routes are ≤4 characters; line codes are
 * 3 letters. One extra `ch` keeps MET / H&C / N253 from clipping.
 */
export const ARRIVALS_IDENTITY_CHIP_WIDTH_CLASS = "w-[5ch]"

/** Unattended rank chip — digit + ordinal suffix (`1st`). */
export const ARRIVALS_RANK_CHIP_WIDTH_CLASS = "w-[3ch]"

export const arrivalsOrdinalSuffix = (
  rank: number
): "st" | "nd" | "rd" | "th" => {
  const abs = Math.abs(Math.trunc(rank))
  const mod100 = abs % 100
  if (mod100 >= 11 && mod100 <= 13) return "th"
  switch (abs % 10) {
    case 1:
      return "st"
    case 2:
      return "nd"
    case 3:
      return "rd"
    default:
      return "th"
  }
}

export const formatArrivalsRankLabel = (rank: number): string =>
  `${rank}${arrivalsOrdinalSuffix(rank)}`

import TflClient from "tfl-ts"

export const getTflClient = (): TflClient => {
  const appKey = process.env.TFL_APP_KEY
  if (!appKey) {
    return new TflClient()
  }
  return new TflClient({ appKey })
}

/** Europe/London calendar helpers — no fixed 24h day length. */

export const LONDON_TIME_ZONE = "Europe/London"

const londonDateFormatter = new Intl.DateTimeFormat("en-CA", {
  timeZone: LONDON_TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
})

const londonWeekdayFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  weekday: "long",
})

const londonDayMonthFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  day: "numeric",
  month: "short",
})

const londonPartsFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23",
})

export type LondonDay = {
  /** YYYY-MM-DD in Europe/London */
  dateKey: string
  /** Inclusive start (UTC ms) of the London calendar day */
  startMs: number
  /** Exclusive end (UTC ms) of the London calendar day */
  endMs: number
  startIso: string
  endIso: string
  weekdayLong: string
  /** Short numeric date for control disambiguation, e.g. "9 Aug" */
  dayMonth: string
  label: "Today" | "Tomorrow" | string
}

const partsMap = (date: Date): Record<string, string> => {
  const out: Record<string, string> = {}
  for (const part of londonPartsFormatter.formatToParts(date)) {
    if (part.type !== "literal") out[part.type] = part.value
  }
  return out
}

/** Calendar date key (YYYY-MM-DD) for an instant in Europe/London. */
export const londonDateKey = (instant: Date = new Date()): string =>
  londonDateFormatter.format(instant)

/** Weekday name in Europe/London, e.g. "Saturday". Pass an explicit instant. */
export const londonWeekdayLong = (nowMs: number): string =>
  londonWeekdayFormatter.format(new Date(nowMs))

/**
 * UTC ms of Europe/London midnight for `dateKey` (YYYY-MM-DD).
 * Iteratively corrects for DST so day length is never assumed to be 24h.
 */
export const londonDayStartMs = (dateKey: string): number => {
  const year = Number(dateKey.slice(0, 4))
  const month = Number(dateKey.slice(5, 7))
  const day = Number(dateKey.slice(8, 10))
  if (!year || !month || !day) {
    throw new Error(`Invalid London date key: ${dateKey}`)
  }

  const desiredAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0)
  let utc = desiredAsUtc

  for (let i = 0; i < 4; i += 1) {
    const parts = partsMap(new Date(utc))
    const localAsUtc = Date.UTC(
      Number(parts.year),
      Number(parts.month) - 1,
      Number(parts.day),
      Number(parts.hour),
      Number(parts.minute),
      Number(parts.second)
    )
    const delta = desiredAsUtc - localAsUtc
    if (delta === 0) break
    utc += delta
  }

  return utc
}

/** Add calendar days in Europe/London (DST-safe via midday probe). */
export const addLondonCalendarDays = (
  dateKey: string,
  days: number
): string => {
  const start = londonDayStartMs(dateKey)
  const probe = new Date(
    start + 12 * 60 * 60 * 1000 + days * 24 * 60 * 60 * 1000
  )
  return londonDateKey(probe)
}

/** Half-open [start, end) bounds for a London calendar day. */
export const londonDayBounds = (
  dateKey: string
): { startMs: number; endMs: number; startIso: string; endIso: string } => {
  const startMs = londonDayStartMs(dateKey)
  const nextKey = addLondonCalendarDays(dateKey, 1)
  const endMs = londonDayStartMs(nextKey)
  return {
    startMs,
    endMs,
    startIso: new Date(startMs).toISOString(),
    endIso: new Date(endMs).toISOString(),
  }
}

export type WeekAheadDayRange = {
  days: LondonDay[]
  /** Inclusive TfL dateRange.startDate (YYYY-MM-DD) */
  startDate: string
  /** Inclusive TfL dateRange.endDate (YYYY-MM-DD) — last displayed day */
  endDate: string
}

/**
 * Eight consecutive Europe/London calendar days starting today.
 * Day 0 Today, day 1 Tomorrow, days 2–7 full weekday names.
 */
export const buildWeekAheadDays = (
  now: Date = new Date()
): WeekAheadDayRange => {
  const todayKey = londonDateKey(now)
  const days: LondonDay[] = []

  for (let offset = 0; offset < 8; offset += 1) {
    const dateKey = addLondonCalendarDays(todayKey, offset)
    const bounds = londonDayBounds(dateKey)
    const midday = new Date(bounds.startMs + 12 * 60 * 60 * 1000)
    const weekdayLong = londonWeekdayFormatter.format(midday)
    const dayMonth = londonDayMonthFormatter.format(midday)
    const label =
      offset === 0 ? "Today" : offset === 1 ? "Tomorrow" : weekdayLong

    days.push({
      dateKey,
      startMs: bounds.startMs,
      endMs: bounds.endMs,
      startIso: bounds.startIso,
      endIso: bounds.endIso,
      weekdayLong,
      dayMonth,
      label,
    })
  }

  return {
    days,
    startDate: days[0]!.dateKey,
    endDate: days[7]!.dateKey,
  }
}

/**
 * Validity overlap for a selected half-open day:
 * period.fromDate < selectedDayEnd && period.toDate > selectedDayStart
 */
export const validityOverlapsDay = (
  period: { fromDate?: string; toDate?: string },
  dayStartMs: number,
  dayEndMs: number
): boolean => {
  if (!period.fromDate || !period.toDate) return false
  const fromMs = Date.parse(period.fromDate)
  const toMs = Date.parse(period.toDate)
  if (Number.isNaN(fromMs) || Number.isNaN(toMs)) return false
  return fromMs < dayEndMs && toMs > dayStartMs
}

import {
  getCurrentLineStatuses,
  getStatusKind,
  getWorstCurrentStatus,
} from "tfl-ts"

export type DisruptionStatus = {
  statusSeverity?: number
  statusSeverityDescription?: string
  reason?: string
  disruption?: {
    category?: string
    categoryDescription?: string
  }
  validityPeriods?: {
    isNow?: boolean
    fromDate?: string
    toDate?: string
  }[]
}

const MODE_REASON_PREFIXES = [
  "London Trams",
  "London Tram",
  "London Overground",
  "Docklands Light Railway",
  "Elizabeth line",
  "Elizabeth Line",
  "DLR",
] as const

const escapeRegExp = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")

const lineReasonPrefixes = (line?: {
  name?: string
  modeName?: string
}): string[] => {
  const prefixes: string[] = [...MODE_REASON_PREFIXES]
  const name = line?.name?.trim()
  if (name) {
    const andName = name.replace(/&/g, "and")
    const ampName = name.replace(/\band\b/gi, "&")
    prefixes.push(name, andName, ampName)
    prefixes.push(`London ${name}`, `London ${andName}`, `London ${name}s`)
  }
  const modeName = line?.modeName?.trim().replace(/-/g, " ")
  if (modeName) {
    prefixes.push(modeName, `${modeName} line`)
  }
  return prefixes
}

/** Drop TfL mode / line prefixes that repeat the card title. */
export const stripStatusReason = (
  reason: string,
  line?: { name?: string; modeName?: string }
): string => {
  const prefixes = [...new Set(lineReasonPrefixes(line))].sort(
    (a, b) => b.length - a.length
  )
  const pattern = new RegExp(
    `^(?:${prefixes.map(escapeRegExp).join("|")})(?:\\s+LINE)?\\s*:\\s*`,
    "i"
  )
  return reason.trim().replace(pattern, "")
}

/** Planned / part closure that replaces a service people expected (`PlannedWork`). */
export const isScheduledEngineeringWork = (status: DisruptionStatus): boolean =>
  getStatusKind(status) === "plannedWork"

const periodOverlapsNow = (
  period: NonNullable<DisruptionStatus["validityPeriods"]>[number],
  now: number
): boolean => {
  const from = period.fromDate
    ? Date.parse(period.fromDate)
    : Number.NEGATIVE_INFINITY
  const to = period.toDate
    ? Date.parse(period.toDate)
    : Number.POSITIVE_INFINITY
  if (Number.isNaN(from) || Number.isNaN(to)) return true
  return now >= from && now <= to
}

/**
 * Live-board operative row: RealTime, no validity window, or a window that
 * overlaps `now`. Not `validityPeriods[].isNow` — that tracks RealTime, so a
 * tram Part Closure can be in force today with `isNow: false`.
 *
 * Pass `now` from cache `fetchedAt`. Omit it only when there is no clock
 * (fixtures / tests that do not care about windows).
 */
export const isCurrentAnnouncement = (
  status: DisruptionStatus,
  now?: number
): boolean => {
  if (status.disruption?.category === "RealTime") return true
  const periods = status.validityPeriods ?? []
  if (periods.length === 0) return true
  if (now === undefined) return true
  return periods.some((period) => periodOverlapsNow(period, now))
}

/** Drop standing hours copy once a RealTime Service Closed row is on the card. */
const dropHoursNoticeWhenClosed = (
  statuses: readonly DisruptionStatus[]
): DisruptionStatus[] => {
  const hasClosedRealtime = statuses.some(
    (status) =>
      status.disruption?.category === "RealTime" &&
      getStatusKind(status) === "closed"
  )
  if (!hasClosedRealtime) return [...statuses]
  return statuses.filter(
    (status) => status.disruption?.category !== "Information"
  )
}

const selectAnnouncementStatuses = (
  statuses: readonly DisruptionStatus[],
  options: { currentOnly: boolean; now?: number }
): DisruptionStatus[] => {
  if (!options.currentOnly) return [...statuses]
  const current = getCurrentLineStatuses(
    statuses,
    options.now !== undefined ? { now: options.now } : undefined
  )
  return dropHoursNoticeWhenClosed(
    current.filter((status) => isCurrentAnnouncement(status, options.now))
  )
}

export type LineAnnouncement = {
  /** Paragraph to render (prefix-stripped unless rawReason). */
  text: string
  /** Worst severity in the merged group — drives chip colour. */
  statusSeverity?: number
  statusSeverityDescription?: string
  disruption?: DisruptionStatus["disruption"]
  /** How many TfL rows collapsed into this paragraph. */
  sourceCount: number
}

export type PrepareLineAnnouncementsOptions = {
  line?: { name?: string; modeName?: string }
  /**
   * Keep operative rows from `getCurrentLineStatuses` (default true).
   * Not `isNow`. Pass `now` from cache `fetchedAt`.
   */
  currentOnly?: boolean
  /** Collapse equal / contained paragraphs. Default true. */
  dedupe?: boolean
  /** Keep TfL's unstripped `reason` string. Default false. */
  rawReason?: boolean
  /** Clock for validity windows. Same stamp as tfl-ts `{ now: fetchedAt }`. */
  now?: number
}

const normalizeAnnouncementKey = (text: string): string =>
  text.toLowerCase().replace(/\s+/g, " ").trim()

const resolveAnnouncementText = (
  status: DisruptionStatus,
  options: { line?: { name?: string; modeName?: string }; rawReason: boolean }
): string => {
  const reason = status.reason?.trim()
  if (reason) {
    return options.rawReason ? reason : stripStatusReason(reason, options.line)
  }
  return status.statusSeverityDescription?.trim() || "Status update"
}

type DraftAnnouncement = LineAnnouncement & {
  key: string
}

const toStatusLike = (draft: DraftAnnouncement): DisruptionStatus => ({
  statusSeverity: draft.statusSeverity,
  statusSeverityDescription: draft.statusSeverityDescription,
  disruption: draft.disruption,
})

/**
 * Passenger-facing announcement list for one line: current filter → text
 * resolution → containment dedupe. All three steps are opt-out via options.
 */
export const prepareLineAnnouncements = (
  statuses: readonly DisruptionStatus[],
  options: PrepareLineAnnouncementsOptions = {}
): readonly LineAnnouncement[] => {
  const currentOnly = options.currentOnly ?? true
  const dedupe = options.dedupe ?? true
  const rawReason = options.rawReason ?? false
  const statusNow = options.now !== undefined ? { now: options.now } : undefined

  const resolved = selectAnnouncementStatuses(statuses, {
    currentOnly,
    now: options.now,
  }).map((status) => {
    const text = resolveAnnouncementText(status, {
      line: options.line,
      rawReason,
    })
    return {
      text,
      key: normalizeAnnouncementKey(text),
      statusSeverity: status.statusSeverity,
      statusSeverityDescription: status.statusSeverityDescription,
      disruption: status.disruption,
      sourceCount: 1,
    } satisfies DraftAnnouncement
  })

  const toAnnouncement = (draft: DraftAnnouncement): LineAnnouncement => ({
    text: draft.text,
    statusSeverity: draft.statusSeverity,
    statusSeverityDescription: draft.statusSeverityDescription,
    disruption: draft.disruption,
    sourceCount: draft.sourceCount,
  })

  if (!dedupe) {
    return resolved.map(toAnnouncement)
  }

  const kept: DraftAnnouncement[] = []

  for (const item of resolved) {
    const matchIndex = kept.findIndex(
      (existing) =>
        existing.key === item.key ||
        existing.key.includes(item.key) ||
        item.key.includes(existing.key)
    )

    if (matchIndex === -1) {
      kept.push(item)
      continue
    }

    const existing = kept[matchIndex]!
    const itemLike = toStatusLike(item)
    const existingLike = toStatusLike(existing)
    const preferIncoming =
      item.key.length > existing.key.length ||
      (item.key.length === existing.key.length &&
        getWorstCurrentStatus([itemLike, existingLike], statusNow) === itemLike)

    const winner = preferIncoming ? item : existing
    const loser = preferIncoming ? existing : item
    const winnerLike = preferIncoming ? itemLike : existingLike
    const loserLike = preferIncoming ? existingLike : itemLike
    const worst =
      getWorstCurrentStatus([winnerLike, loserLike], statusNow) ?? winnerLike

    kept[matchIndex] = {
      text: winner.text,
      key: winner.key,
      statusSeverity: worst.statusSeverity,
      statusSeverityDescription: worst.statusSeverityDescription,
      disruption: worst.disruption,
      sourceCount: winner.sourceCount + loser.sourceCount,
    }
  }

  return kept.map(toAnnouncement)
}
